      ro: ["Poziție strategică pe ruta maritimă a Capului Bunei Speranțe", "Principalul punct de ieșire pentru fructele și vinurile țării", "Găzduiește zona turistică celebră Victoria & Alfred Waterfront", "Centru major pentru construcția și repararea navelor", "Baza principală pentru flota de pescuit oceanic", "Dispune de un terminal de croazieră de talie mondială"],
      en: ["Strategic location on the sea route around the Cape", "Main gateway for South African fruit and wine exports", "Home to the popular Victoria & Alfred Waterfront precinct", "Significant hub for ship repair and marine engineering", "Core base for the South African deep-sea fishing industry", "Operational center for South Atlantic cruise tourism"],
      es: ["Fundado en 1652", "28 atraques", "Manipulación anual: aprox. 10 millones de toneladas", "Profundidad del agua: 14 m", "Superficie: 10 km²", "Emplea directamente a más de 5.000 personas"],
