      ro: ["Cea mai mare mină de diamante din Africa de Sud.", "Inaugurată de Harry Oppenheimer în anul 1992.", "Produce 40% din diamantele Africii de Sud.", "Este operată de către grupul De Beers.", "Investiție de 2 miliarde USD pentru mina subterană.", "Se învecinează cu Rezervația Naturală Venetia Limpopo."],
      en: ["Largest diamond mine in all of South Africa.", "Opened by Harry Oppenheimer in 1992.", "Produces 40% of the nation's total diamond output.", "Owned and operated by the De Beers Group.", "Undergoing a $2 billion underground expansion.", "Borders the Venetia Limpopo Nature Reserve."],
      es: ["La mina Venetia produce unos 4 millones de quilates de diamantes al año.", "La mina a cielo abierto alcanza una profundidad de más de 450 metros.", "La producción comenzó en 1992.", "Emplea a unas 3.600 personas.", "La vida útil estimada llega hasta 2040.", "La mina está cerca de la frontera con Zimbabue."],
      pt: ["A mina de Venetia produz cerca de 4 milhões de quilates de diamantes por ano.", "A mina a céu aberto atinge uma profundidade superior a 450 metros.", "A produção começou em 1992.", "Emprega cerca de 3.600 pessoas.", "A vida útil estimada vai até 2040.", "A mina situa-se perto da fronteira com o Zimbabué."],
      fr: ["La mine de Venetia produit environ 4 millions de carats de diamants par an.", "La mine à ciel ouvert atteint plus de 450 mètres de profondeur.", "La production a débuté en 1992.", "Elle emploie environ 3 600 personnes.", "La durée de vie estimée va jusqu'en 2040.", "La mine est proche de la frontière avec le Zimbabwe."],
